// /sui/assets.js — generated by the mc-semantic-ui asset registry
// (ai.mindconnect.ui.assets.SuiAssetRegistry) from every META-INF/sui/assets.json
// on the server's classpath, every SuiAssetContribution bean and every asset
// registered at run time. Registry generation: /*SUI_GENERATION*/0
//
//     import { installAll } from "/sui/assets.js";
//     await installAll(renderer, bus);   // before the first render

/**
 * The resolved assets, in load order: `{ id, kind, url }`, kind one of css,
 * module, extension, icons — an icon set also carries its `prefix`.
 */
const ASSETS = /*SUI_ASSETS*/[];

/**
 * An asset's url, resolved against this module's own location — so a server
 * path (`/sui-ext/…`) stays on the module's origin, and a relative one
 * (`../sui-ext/…`, as a static export writes it) works wherever the files are
 * hosted, for a stylesheet linked into the page as much as for an import.
 */
const resolve = (url) => new URL(url, import.meta.url).href;

/**
 * Adds every icon set to the renderer's icon module — `renderer.addIconSprite`,
 * so the sets land in the module instance the renderer really renders with.
 * Synchronous and first, so the first render already finds them. Returns the
 * report rows, one per icon set.
 */
function installIcons(renderer) {
    const report = [];
    for (const asset of ASSETS) {
        if (asset.kind !== "icons") continue;
        try {
            if (!renderer || typeof renderer.addIconSprite !== "function") {
                throw new Error("the renderer has no addIconSprite(prefix, url)");
            }
            renderer.addIconSprite(asset.prefix, resolve(asset.url));
            report.push({ id: asset.id, ok: true });
        } catch (err) {
            console.error(`sui-assets: icon set "${asset.id}" (${asset.url}) could not be added; the rest go on`, err);
            report.push({ id: asset.id, ok: false, error: String((err && err.message) || err) });
        }
    }
    return report;
}

export const assets = ASSETS;

/**
 * Links every css asset the page does not carry yet — a server-rendered head
 * may already have them, marked `data-sui-asset`. Resolves when they have
 * loaded or failed, so a first render does not flash unstyled. A page with no
 * document (a test, a worker) has nothing to link.
 */
export function linkStyles(doc = globalThis.document) {
    if (!doc || !doc.head) return Promise.resolve();
    const present = new Set(Array.from(doc.querySelectorAll("link[data-sui-asset]"),
        link => link.getAttribute("data-sui-asset")));
    const pending = [];
    for (const asset of ASSETS) {
        if (asset.kind !== "css" || present.has(asset.id)) continue;
        const link = doc.createElement("link");
        link.rel = "stylesheet";
        link.href = resolve(asset.url);
        link.setAttribute("data-sui-asset", asset.id);
        pending.push(new Promise(resolve => { link.onload = link.onerror = () => resolve(); }));
        doc.head.appendChild(link);
    }
    return Promise.all(pending).then(() => undefined);
}

/**
 * Links the stylesheets, adds the icon sets, imports every module and
 * extension, and calls
 * `install(renderer, { bus })` on each extension, in order. The imports start
 * together; the installs run one after another in the registry's order, so an
 * extension that builds on another finds it installed.
 *
 * One asset that fails — a module that does not load, an extension without
 * `install`, an `install` that throws — is logged and skipped; the others go
 * on. Resolves, after the stylesheets have loaded, to a report:
 * `[{ id, ok, error? }]`.
 *
 * `options.document` is the document to link the stylesheets into (the
 * page's by default).
 */
export async function installAll(renderer, bus, options = {}) {
    const styles = linkStyles(options.document ?? globalThis.document);
    const report = installIcons(renderer);
    const code = ASSETS.filter(asset => asset.kind === "module" || asset.kind === "extension");
    const loads = code.map(asset => import(resolve(asset.url)).then(mod => ({ mod }), error => ({ error })));
    for (let i = 0; i < code.length; i++) {
        const asset = code[i];
        const { mod, error } = await loads[i];
        try {
            if (error) throw error;
            if (asset.kind === "extension") {
                if (typeof mod.install !== "function") {
                    throw new Error("the module exports no install(renderer, { bus })");
                }
                await mod.install(renderer, { bus });
            }
            report.push({ id: asset.id, ok: true });
        } catch (err) {
            console.error(`sui-assets: "${asset.id}" (${asset.url}) could not be ${error ? "loaded" : "installed"}; the rest go on`, err);
            report.push({ id: asset.id, ok: false, error: String((err && err.message) || err) });
        }
    }
    await styles;
    // A node whose renderer an extension just brought — on a server-rendered
    // page, or drawn before the install — is still its placeholder: redraw it.
    const doc = options.document ?? globalThis.document;
    try {
        if (doc && typeof renderer?.upgradePlaceholders === "function") renderer.upgradePlaceholders(doc);
    } catch (err) {
        console.error("sui-assets: could not redraw the placeholders", err);
    }
    return report;
}
